import{_ as l,a0 as p,w as n,s as o,ao as d,I as s,x as e,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"用 Spark SQL 进行结构化数据处理 | LCTT x X-CMD","titleTemplate":false,"description":"用 Spark SQL 进行结构化数据处理 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Spark SQL 进行结构化数据处理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Spark SQL 进行结构化数据处理 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220516 Structured Data Processing with Spark SQL","title":"用 Spark SQL 进行结构化数据处理","tag":"202205","desc":""},"relativePath":"202205/20220516 Structured Data Processing with Spark SQL.md","filePath":"[post].md"}'),h={name:"202205/20220516 Structured Data Processing with Spark SQL.md"};function k(u,a,S,c,b,g){const r=p("Link");return n(),o("div",null,[a[15]||(a[15]=d('<h1 id="用-spark-sql-进行结构化数据处理" tabindex="-1">用 Spark SQL 进行结构化数据处理 <a class="header-anchor" href="#用-spark-sql-进行结构化数据处理" aria-label="Permalink to “用 Spark SQL 进行结构化数据处理”">​</a></h1><blockquote><p>Spark SQL 是 Spark 生态系统中处理结构化格式数据的模块。它在内部使用 Spark Core API 进行处理，但对用户的使用进行了抽象。这篇文章深入浅出地告诉你 Spark SQL 3.x 的新内容。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202205/24/093036xaf6kaz1auaf4a7s.jpg" alt=""></p><p>有了 Spark SQL，用户可以编写 SQL 风格的查询。这对于精通结构化查询语言或 SQL 的广大用户群体来说，基本上是很有帮助的。用户也将能够在结构化数据上编写交互式和临时性的查询。Spark SQL 弥补了<ruby>弹性分布式数据集<rt>resilient distributed data sets</rt></ruby>（RDD）和关系表之间的差距。RDD 是 Spark 的基本数据结构。它将数据作为分布式对象存储在适合并行处理的节点集群中。RDD 很适合底层处理，但在运行时很难调试，程序员不能自动推断<ruby>模式<rt>schema</rt></ruby>。另外，RDD 没有内置的优化功能。Spark SQL 提供了<ruby>数据帧<rt>DataFrame</rt></ruby>和数据集来解决这些问题。</p><p>Spark SQL 可以使用现有的 Hive 元存储、SerDes 和 UDF。它可以使用 JDBC/ODBC 连接到现有的 BI 工具。</p><h3 id="数据源" tabindex="-1">数据源 <a class="header-anchor" href="#数据源" aria-label="Permalink to “数据源”">​</a></h3><p>大数据处理通常需要处理不同的文件类型和数据源（关系型和非关系型）的能力。Spark SQL 支持一个统一的数据帧接口来处理不同类型的源，如下所示。</p><ul><li>文件： <ul><li>CSV</li><li>Text</li><li>JSON</li><li>XML</li></ul></li><li>JDBC/ODBC： <ul><li>MySQL</li><li>Oracle</li><li>Postgres</li></ul></li><li>带模式的文件： <ul><li>AVRO</li><li>Parquet</li></ul></li><li>Hive 表： <ul><li>Spark SQL 也支持读写存储在 Apache Hive 中的数据。</li></ul></li></ul><p>通过数据帧，用户可以无缝地读取这些多样化的数据源，并对其进行转换/连接。</p><h3 id="spark-sql-3-x-的新内容" tabindex="-1">Spark SQL 3.x 的新内容 <a class="header-anchor" href="#spark-sql-3-x-的新内容" aria-label="Permalink to “Spark SQL 3.x 的新内容”">​</a></h3><p>在以前的版本中（Spark 2.x），查询计划是基于启发式规则和成本估算的。从解析到逻辑和物理查询计划，最后到优化的过程是连续的。这些版本对转换和行动的运行时特性几乎没有可见性。因此，由于以下原因，查询计划是次优的：</p><ul><li>缺失和过时的统计数据</li><li>次优的启发式方法</li><li>错误的成本估计</li></ul><p>Spark 3.x 通过使用运行时数据来迭代改进查询计划和优化，增强了这个过程。前一阶段的运行时统计数据被用来优化后续阶段的查询计划。这里有一个反馈回路，有助于重新规划和重新优化执行计划。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-1-Query-planning.jpg" alt="Figure 1: Query planning"></p><h4 id="自适应查询执行-aqe" tabindex="-1">自适应查询执行（AQE） <a class="header-anchor" href="#自适应查询执行-aqe" aria-label="Permalink to “自适应查询执行（AQE）”">​</a></h4><p>查询被改变为逻辑计划，最后变成物理计划。这里的概念是“重新优化”。它利用前一阶段的可用数据，为后续阶段重新优化。正因为如此，整个查询的执行要快得多。</p><p>AQE 可以通过设置 SQL 配置来启用，如下所示（Spark 3.0 中默认为 false）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>spark.conf.set(“spark.sql.adaptive.enabled”,true)</span></span></code></pre></div><h4 id="动态合并-洗牌-分区" tabindex="-1">动态合并“洗牌”分区 <a class="header-anchor" href="#动态合并-洗牌-分区" aria-label="Permalink to “动态合并“洗牌”分区”">​</a></h4><p>Spark 在“<ruby>洗牌<rt>shuffle</rt></ruby>”操作后确定最佳的分区数量。在 AQE 中，Spark 使用默认的分区数，即 200 个。这可以通过配置来启用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>spark.conf.set(“spark.sql.adaptive.coalescePartitions.enabled”,true)</span></span></code></pre></div><h4 id="动态切换连接策略" tabindex="-1">动态切换连接策略 <a class="header-anchor" href="#动态切换连接策略" aria-label="Permalink to “动态切换连接策略”">​</a></h4><p>广播哈希是最好的连接操作。如果其中一个数据集很小，Spark 可以动态地切换到广播连接，而不是在网络上“洗牌”大量的数据。</p><h4 id="动态优化倾斜连接" tabindex="-1">动态优化倾斜连接 <a class="header-anchor" href="#动态优化倾斜连接" aria-label="Permalink to “动态优化倾斜连接”">​</a></h4><p>如果数据分布不均匀，数据会出现倾斜，会有一些大的分区。这些分区占用了大量的时间。Spark 3.x 通过将大分区分割成多个小分区来进行优化。这可以通过设置来启用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>spark.conf.set(“spark.sql.adaptive.skewJoin.enabled”,true)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-2-Performance-improvement-in-Spark-3.x-Source-Databricks.jpg" alt="Figure 2: Performance improvement in Spark 3.x (Source: Databricks)"></p><h3 id="其他改进措施" tabindex="-1">其他改进措施 <a class="header-anchor" href="#其他改进措施" aria-label="Permalink to “其他改进措施”">​</a></h3><p>此外，Spark SQL 3.x还支持以下内容。</p><h4 id="动态分区修剪" tabindex="-1">动态分区修剪 <a class="header-anchor" href="#动态分区修剪" aria-label="Permalink to “动态分区修剪”">​</a></h4><p>3.x 将只读取基于其中一个表的值的相关分区。这消除了解析大表的需要。</p><h4 id="连接提示" tabindex="-1">连接提示 <a class="header-anchor" href="#连接提示" aria-label="Permalink to “连接提示”">​</a></h4><p>如果用户对数据有了解，这允许用户指定要使用的连接策略。这增强了查询的执行过程。</p><h4 id="兼容-ansi-sql" tabindex="-1">兼容 ANSI SQL <a class="header-anchor" href="#兼容-ansi-sql" aria-label="Permalink to “兼容 ANSI SQL”">​</a></h4><p>在兼容 Hive 的早期版本的 Spark 中，我们可以在查询中使用某些关键词，这样做是完全可行的。然而，这在 Spark SQL 3 中是不允许的，因为它有完整的 ANSI SQL 支持。例如，“将字符串转换为整数”会在运行时产生异常。它还支持保留关键字。</p><h4 id="较新的-hadoop、java-和-scala-版本" tabindex="-1">较新的 Hadoop、Java 和 Scala 版本 <a class="header-anchor" href="#较新的-hadoop、java-和-scala-版本" aria-label="Permalink to “较新的 Hadoop、Java 和 Scala 版本”">​</a></h4><p>从 Spark 3.0 开始，支持 Java 11 和 Scala 2.12。 Java 11 具有更好的原生协调和垃圾校正，从而带来更好的性能。 Scala 2.12 利用了 Java 8 的新特性，优于 2.11。</p><p>Spark 3.x 提供了这些现成的有用功能，而无需开发人员操心。这将显着提高 Spark 的整体性能。</p><hr>',39)),s("p",null,[a[1]||(a[1]=e("via: ",-1)),t(r,{href:"https://www.opensourceforu.com/2022/05/structured-data-processing-with-spark-sql/"},{default:i(()=>[...a[0]||(a[0]=[e("https://www.opensourceforu.com/2022/05/structured-data-processing-with-spark-sql/",-1)])]),_:1})]),s("p",null,[a[6]||(a[6]=e("作者：",-1)),t(r,{href:"https://www.opensourceforu.com/author/phani-kiran/"},{default:i(()=>[...a[2]||(a[2]=[e("Phani Kiran",-1)])]),_:1}),a[7]||(a[7]=e(" 选题：",-1)),t(r,{href:"https://github.com/lkxed"},{default:i(()=>[...a[3]||(a[3]=[e("lkxed",-1)])]),_:1}),a[8]||(a[8]=e(" 译者：",-1)),t(r,{href:"https://github.com/geekpi"},{default:i(()=>[...a[4]||(a[4]=[e("geekpi",-1)])]),_:1}),a[9]||(a[9]=e(" 校对：",-1)),t(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[a[12]||(a[12]=e("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原创编译，",-1)),t(r,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[e("Linux中国",-1)])]),_:1}),a[14]||(a[14]=e(" 荣誉推出",-1))])])}const L=l(h,[["render",k]]);export{x as __pageData,L as default};
